{"source": {"declaration": "FUNCTION_BLOCK FB_Task
VAR_INPUT
  ManualMode : BOOL;
  SingleStepMode : BOOL;
  SingleCycleMode : BOOL;
  ContinuousMode : BOOL;
  EmergencyStop : BOOL;
  Start : BOOL;
  DownButton : BOOL;
  UpButton : BOOL;
  LeftButton : BOOL;
  RightButton : BOOL;
  GripButton : BOOL;
  ReleaseButton : BOOL;
  DownLimitSwitch : BOOL;
  UpLimitSwitch : BOOL;
  LeftLimitSwitch : BOOL;
  RightLimitSwitch : BOOL;
  GripLimitSwitch : BOOL;
  ReleaseLimitSwitch : BOOL;
END_VAR
VAR_OUTPUT
  MoveDown : BOOL;
  MoveUp : BOOL;
  MoveLeft : BOOL;
  MoveRight : BOOL;
  ActivateGrip : BOOL;
  ActivateRelease : BOOL;
END_VAR
VAR
  phase : INT := 0;
  nextStep : INT := 1;
  busy : BOOL := FALSE;
  prevStart : BOOL := FALSE;
  prevMode : INT := -1;
  modeCode : INT := 0;
  startEdge : BOOL := FALSE;
  fb : BOOL := FALSE;
END_VAR", "implementation": "modeCode := 0;
IF ManualMode THEN
  modeCode := 1;
ELSIF SingleStepMode THEN
  modeCode := 2;
ELSIF SingleCycleMode THEN
  modeCode := 3;
ELSIF ContinuousMode THEN
  modeCode := 4;
END_IF

startEdge := Start AND NOT prevStart;

MoveDown := FALSE;
MoveUp := FALSE;
MoveLeft := FALSE;
MoveRight := FALSE;
ActivateGrip := FALSE;
ActivateRelease := FALSE;

IF (NOT EmergencyStop) OR (modeCode = 0) THEN
  busy := FALSE;
  phase := 0;
  nextStep := 1;
ELSE
  IF modeCode <> prevMode THEN
    busy := FALSE;
    phase := 0;
    nextStep := 1;
  END_IF

  IF modeCode = 1 THEN
    MoveDown := DownButton AND NOT UpButton AND NOT DownLimitSwitch;
    MoveUp := UpButton AND NOT DownButton AND NOT UpLimitSwitch;
    MoveLeft := LeftButton AND NOT RightButton AND NOT LeftLimitSwitch;
    MoveRight := RightButton AND NOT LeftButton AND NOT RightLimitSwitch;
    ActivateGrip := GripButton AND NOT ReleaseButton AND NOT GripLimitSwitch;
    ActivateRelease := ReleaseButton AND NOT GripButton AND NOT ReleaseLimitSwitch;
  ELSE
    IF busy THEN
      fb := FALSE;
      CASE phase OF
        1: fb := DownLimitSwitch;
        2: fb := GripLimitSwitch;
        3: fb := UpLimitSwitch;
        4: fb := RightLimitSwitch;
        5: fb := DownLimitSwitch;
        6: fb := ReleaseLimitSwitch;
        7: fb := UpLimitSwitch;
        8: fb := LeftLimitSwitch;
      END_CASE
      IF fb THEN
        IF modeCode = 2 THEN
          nextStep := phase + 1;
          IF nextStep > 8 THEN
            nextStep := 1;
          END_IF
          busy := FALSE;
          phase := 0;
        ELSIF modeCode = 3 THEN
          IF phase = 8 THEN
            busy := FALSE;
            phase := 0;
          ELSE
            phase := phase + 1;
          END_IF
        ELSE
          IF phase = 8 THEN
            phase := 1;
          ELSE
            phase := phase + 1;
          END_IF
        END_IF
      END_IF

